first = list_contacts({ page: 1 })
remaining = for page in list.range(2, first.total_pages + 1) {
    result = list_contacts({ page })
    return result.items
}
contacts = fold acc = first.items for page in remaining {
    return acc + page
}

# Build domain -> company name map
domain_map = fold acc = {} for c in companies {
    return acc + { [c.domain]: c.name }
}

# Digits helper via regex
normalize_phone = fun(p) {
    # Extract digits only
    return p
}

results = for contact in contacts {
    phone_fixed = false
    company_filled = false
    new_phone = null
    new_company = null

    # Check phone E.164: +1 followed by exactly 10 digits
    phone = contact.phone if contact.phone != null else ""
    valid = regex.test(phone, "^\\+1\\d{10}$")
    if not valid and phone != "" {
        # Extract all digits
        caps = regex.find_all(phone, "\\d")
        digits = text.join(caps, "")
        # If 11 digits starting with 1, use last 10; if 10 digits, use them; else try what we can
        d10 = if text.length(digits) == 11 and text.starts_with(digits, "1") {
            return text.slice(digits, 1, 11)
        } else if text.length(digits) >= 10 {
            # take last 10 digits
            return text.slice(digits, text.length(digits) - 10, text.length(digits))
        } else {
            return digits
        }
        candidate = "+1" + d10
        if regex.test(candidate, "^\\+1\\d{10}$") and candidate != phone {
            new_phone = candidate
            phone_fixed = true
        }
    }

    # Company fill
    company = contact.company if contact.company != null else ""
    email = contact.email if contact.email != null else ""
    if company == "" and email != "" {
        parts = text.split(email, "@")
        domain = parts[1] if list.length(parts) >= 2 else ""
        if domain != "" and domain in domain_map {
            new_company = domain_map[domain]
            company_filled = true
        }
    }

    updated = null
    if phone_fixed or company_filled {
        updated = update_contact({
            id: contact.id,
            phone: new_phone if phone_fixed else null,
            company: new_company if company_filled else null
        })
    }

    return {
        phone_fixed: phone_fixed,
        company_filled: company_filled
    }
}

phones_fixed = fold acc = 0 for r in results {
    return acc + (1 if r.phone_fixed else 0)
}
companies_filled = fold acc = 0 for r in results {
    return acc + (1 if r.company_filled else 0)
}

submit = submit_result({ answer: { phones_fixed: phones_fixed, companies_filled: companies_filled } })
return { phones_fixed, companies_filled, submit }

